import json, datetime
from pathlib import Path
from contact import P, sha, write
r = json.load(open(P / 'PREREG_R1.json'))
r.update(round='R2', frozen_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(), capability='Retain noncontact opposition geometry alongside continuous contact map so anterior bite, M1 relationship and toothwise crossbite can be queried even without contact; expose information loss of contact-only representation.', obstacle='A contact edge has no information about separated incisor AP position, and M1 contact location alone does not identify cusp/groove identity.', changed_operation='Augment R1 geometry with X11 explicit opposing crown/landmark candidates in one lower-jaw frame. For every corresponding tooth pair preserve signed buccal/anterior order, candidate incisal overbite/overjet and cusp-groove M1 relation. Preserve target identity/point validation UNKNOWN. No fit selection or threshold adjustment from R1.')
r['fit']['features'] = 'All frozen R1 features + X11 numeric named-landmark port + signed toothwise opposition margins + same-frame tooth/cusp coordinates; geometry only. Same fixed HGB recipe.'
r['gates']['report'] = dict(min_scored_cases_per_field=100, macro_balanced_accuracy_min=0.65, all_report_possible_set_coverage_min=0.85, mean_set_size_max=2.5, decision='Same capability thresholds as R1; no claim of superiority against R1 or X7; legacy descriptive test reuse.')
r['gates']['toothwise_crossbite'] = dict(rule='Corresponding U1/L4 or U2/L3 tooth; posterior/canine MB-cusp ordering along predicted lower buccal unit; incisors incisal tip ordering along common anterior unit; margin<0 predicts reversed ordering. 0mm is geometric order threshold, not clinical diagnostic threshold.', uncertainty='Hypothetical 0.5mm coordinate error at each point gives ±1mm signed margin scenario, target error unmeasured.', quantity='Recall of explicitly named positive upper-equivalent teeth; specificity on explicit absence reports; descriptive Dice for reports listing teeth; unlisted teeth in a positive report are not established negatives.', recall_min=0.7, absent_specificity_min=0.7, min_named_cases=30, decision='PASS only if both gates pass; reported tooth-list completeness remains UNKNOWN.')
r['gates']['point_measurements'] = dict(overbite='minus upper-lower incisal diff along superior', overjet='upper-lower incisal diff along anterior', Angle='upper M1 mesiobuccal-cusp candidate minus lower M1 buccal-groove candidate projected on lower M1 mesial direction', decision='Anatomical millimeter accuracy remains UNKNOWN until an external point measurement is available; categorical agreement cannot establish it.')
r['falsifiers'] += ['Signed-order rule fails named-crossbite recall or explicit-negative specificity', 'X11 named points or buccal axes are not anatomically correct; geometric order can be evaluated but not declared clinical truth']
write(P / 'PREREG_R2.json', r)
(P / 'PREREG_R2.json.sha256').write_text(sha(P / 'PREREG_R2.json') + '\n')
write(P / 'DECOMPOSITION_R2.json', dict(idea=r['capability'], leaves=[dict(name='noncontact information loss', status='DERIVED_UNDER_ASSUMPTIONS', relation='If no opposing pair is within h and clearance margin m>0, any perturbation smaller than m preserves empty contact edges while incisor AP differences can vary. Therefore edge graph alone cannot identify overjet.', stopping_argument='Elementary noninjective map; adding force law cannot restore deleted position information.'), dict(name='opposition order', status='DERIVED_UNDER_ASSUMPTIONS', relation='b=(p_upper-p_lower) dot lower_buccal_unit; b<0 is reversed buccal order, anterior substitutes anterior unit.', stopping_argument='Exact coordinate comparison given points/axes; identification as clinical crossbite is an unvalidated closure.'), dict(name='named point anatomy', status='UNKNOWN', relation='X11 extremum candidates; no independent Bite2Text landmark labels.', stopping_argument='Cannot derive named cusp from extremum without annotation or validated morphology model.'), dict(name='coordinate error scenario', status='CONSTITUTIVE_CLOSURE', relation='|delta b| <= ||delta p_u||+||delta p_l||=1mm if each <=0.5mm and unit direction fixed.', stopping_argument='Bound derived but 0.5mm premise unmeasured; axis and segmentation uncertainty excluded.'), dict(name='crossbite facit', status='EXTERNALLY_MEASURED', relation='X7 source report tooth numbers and explicit absent/present judgments.', stopping_argument='Descriptions may be incomplete and disagree; no unlisted-tooth negative ground truth.')]))
print('R2 frozen', sha(P / 'PREREG_R2.json'))
